## 1. Compreensão do problema

O objetivo é encontrar o menor tempo para viajar da ilha `X` à ilha `Y`, sem gastar mais que o orçamento disponível. Se não existir uma rota que respeite o orçamento, a resposta é `-1`.

A entrada contém uma única instância: orçamento, número de ilhas, número de rotas, as rotas e, por fim, as ilhas de origem e destino. A saída é um único inteiro.

Restrições importantes:

- `2 ≤ N ≤ 10000`, `1 ≤ M ≤ 2000` e orçamento `1 ≤ V ≤ 200`.
- As rotas podem ser percorridas nos dois sentidos.
- O custo pode ser zero, mas tempo e custo nunca são negativos.
- O grafo pode ser desconexo e pode haver rotas paralelas.
- `N = 0` e `N = 1` não são casos permitidos pelas restrições. Se origem e destino forem iguais, a resposta é `0`.
- Mesmo que os tempos acumulados caibam nos limites usuais deste problema, usaremos `long long` para as distâncias.

## 2. Planejamento e design algorítmico

Usaremos **Dijkstra em um grafo de estados**. Um estado é formado por uma ilha e pelo custo já gasto: `(ilha, custo)`.

Assim, cada estado representa uma posição alcançada gastando exatamente determinado valor. Ao percorrer uma rota de custo `P`, o novo estado só é considerado se o custo total continuar dentro do orçamento. Como os tempos são não negativos, Dijkstra encontra o menor tempo para cada estado.

O algoritmo termina quando remove da fila de prioridade o primeiro estado cuja ilha é `Y`: ele tem o menor tempo entre todos os estados de destino possíveis.

- Número de estados: `N × (V + 1)`.
- Transições consideradas: no máximo `2M × (V + 1)`.
- Tempo: `O((N·V + M·V) log(N·V + M·V))`.
- Memória: `O(N·V + M·V)` no pior caso, incluindo a fila de prioridade.

Com os limites dados, essa abordagem é adequada.

## 3. Codificação em C

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int to;
    int time;
    int cost;
    int next;
} Edge;

typedef struct {
    long long distance;
    int state;
} HeapItem;

typedef struct {
    HeapItem *items;
    size_t size;
    size_t capacity;
} MinHeap;

static int heap_push(MinHeap *heap, HeapItem item) {
    if (heap->size == heap->capacity) {
        size_t new_capacity = heap->capacity == 0 ? 1024 : heap->capacity * 2;
        HeapItem *new_items = realloc(heap->items, new_capacity * sizeof(*new_items));
        if (new_items == NULL) {
            return 0;
        }
        heap->items = new_items;
        heap->capacity = new_capacity;
    }

    size_t i = heap->size++;
    while (i > 0) {
        size_t parent = (i - 1) / 2;
        if (heap->items[parent].distance <= item.distance) {
            break;
        }
        heap->items[i] = heap->items[parent];
        i = parent;
    }
    heap->items[i] = item;
    return 1;
}

static HeapItem heap_pop(MinHeap *heap) {
    HeapItem result = heap->items[0];
    HeapItem last = heap->items[--heap->size];

    if (heap->size > 0) {
        size_t i = 0;
        while (1) {
            size_t left = 2 * i + 1;
            size_t right = left + 1;

            if (left >= heap->size) {
                break;
            }

            size_t smallest = left;
            if (right < heap->size &&
                heap->items[right].distance < heap->items[left].distance) {
                smallest = right;
            }

            if (heap->items[smallest].distance >= last.distance) {
                break;
            }

            heap->items[i] = heap->items[smallest];
            i = smallest;
        }
        heap->items[i] = last;
    }

    return result;
}

int main(void) {
    int budget, n, m;
    if (scanf("%d %d %d", &budget, &n, &m) != 3) {
        return 0;
    }

    int *head = malloc((size_t)n * sizeof(*head));
    Edge *edges = malloc((size_t)(2 * m) * sizeof(*edges));
    if (head == NULL || edges == NULL) {
        free(head);
        free(edges);
        return 0;
    }

    for (int i = 0; i < n; i++) {
        head[i] = -1;
    }

    int edge_count = 0;
    for (int i = 0; i < m; i++) {
        int a, b, time, cost;
        scanf("%d %d %d %d", &a, &b, &time, &cost);
        --a;
        --b;

        edges[edge_count] = (Edge){b, time, cost, head[a]};
        head[a] = edge_count++;

        edges[edge_count] = (Edge){a, time, cost, head[b]};
        head[b] = edge_count++;
    }

    int x, y;
    scanf("%d %d", &x, &y);
    --x;
    --y;

    int width = budget + 1;
    int state_count = n * width;
    long long *dist = malloc((size_t)state_count * sizeof(*dist));
    if (dist == NULL) {
        free(head);
        free(edges);
        return 0;
    }

    const long long INF = LLONG_MAX / 4;
    for (int i = 0; i < state_count; i++) {
        dist[i] = INF;
    }

    MinHeap heap = {NULL, 0, 0};
    int start_state = x * width;  /* origem, com custo gasto igual a zero */
    dist[start_state] = 0;

    if (!heap_push(&heap, (HeapItem){0, start_state})) {
        free(head);
        free(edges);
        free(dist);
        return 0;
    }

    long long answer = -1;

    while (heap.size > 0) {
        HeapItem current = heap_pop(&heap);

        if (current.distance != dist[current.state]) {
            continue;
        }

        int island = current.state / width;
        int spent = current.state % width;

        if (island == y) {
            answer = current.distance;
            break;
        }

        for (int e = head[island]; e != -1; e = edges[e].next) {
            int new_spent = spent + edges[e].cost;
            if (new_spent > budget) {
                continue;
            }

            int next_state = edges[e].to * width + new_spent;
            long long new_distance = current.distance + edges[e].time;

            if (new_distance < dist[next_state]) {
                dist[next_state] = new_distance;
                if (!heap_push(&heap, (HeapItem){new_distance, next_state})) {
                    free(head);
                    free(edges);
                    free(dist);
                    free(heap.items);
                    return 0;
                }
            }
        }
    }

    printf("%lld\n", answer);

    free(head);
    free(edges);
    free(dist);
    free(heap.items);
    return 0;
}
```

## 4. Retrospecto e verificação

No primeiro exemplo, Dijkstra considera os estados de custo gasto até `10` e encontra o destino com tempo `5`. No segundo, nenhuma rota até o destino cabe no orçamento, então a saída é `-1`.

A implementação também lida com grafos desconexos, rotas paralelas, rotas de custo zero e origem igual ao destino. O orçamento é respeitado em cada transição, e a fila de prioridade garante que o primeiro estado de destino removido tenha o menor tempo possível.

